<?php
require __DIR__ . '/includes/bootstrap.php';
require __DIR__ . '/includes/ai.php';
$user=require_role('admin'); $pdo=db();
$month=(string)($_GET['month'] ?? $_POST['month'] ?? date('Y-m')); if (!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)) $month=date('Y-m');
$start=$month.'-01'; $end=date('Y-m-d',strtotime($start.' +1 month'));
$q=$pdo->prepare("SELECT COUNT(*) total, SUM(status='pending') pending, SUM(type='expense' AND status='approved' AND amount IS NOT NULL) approved_expenses, COALESCE(SUM(CASE WHEN type='expense' AND status='approved' THEN amount ELSE 0 END),0) spending, SUM(type='expense' AND status='approved' AND amount IS NULL) missing_amount FROM reports WHERE created_at>=? AND created_at<?"); $q->execute([$start,$end]); $stats=$q->fetch();
$q=$pdo->prepare("SELECT u.id,u.name,COUNT(r.id) report_count, SUM(r.status='pending') pending, COALESCE(SUM(CASE WHEN r.type='expense' AND r.status='approved' THEN r.amount ELSE 0 END),0) spending FROM users u LEFT JOIN reports r ON r.user_id=u.id AND r.created_at>=? AND r.created_at<? WHERE u.role='worker' AND u.active=1 GROUP BY u.id,u.name ORDER BY report_count DESC,u.name"); $q->execute([$start,$end]); $workersMonth=$q->fetchAll();
$q=$pdo->prepare("SELECT COALESCE(NULLIF(category,''),'Uncategorized') category, COUNT(*) total, COALESCE(SUM(amount),0) spending FROM reports WHERE type='expense' AND status='approved' AND created_at>=? AND created_at<? GROUP BY COALESCE(NULLIF(category,''),'Uncategorized') ORDER BY spending DESC"); $q->execute([$start,$end]); $categories=$q->fetchAll();
$q=$pdo->prepare("SELECT DATE(created_at) day, COUNT(*) total, SUM(status='pending') pending, COALESCE(SUM(CASE WHEN type='expense' AND status='approved' THEN amount ELSE 0 END),0) spending FROM reports WHERE created_at>=? AND created_at<? GROUP BY DATE(created_at) ORDER BY day DESC"); $q->execute([$start,$end]); $daily=$q->fetchAll();
$q=$pdo->prepare("SELECT project_id,COALESCE(SUM(amount),0) spending FROM reports WHERE type='expense' AND status='approved' AND created_at>=? AND created_at<? GROUP BY project_id"); $q->execute([$start,$end]); $projectSpending=[]; foreach($q->fetchAll() as $row) if ($row['project_id']!==null) $projectSpending[(int)$row['project_id']]=$row['spending'];
$q=$pdo->prepare('SELECT type, COUNT(*) total FROM reports WHERE created_at>=? AND created_at<? GROUP BY type'); $q->execute([$start,$end]); $typeStats=$q->fetchAll();
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action'] ?? '')==='monthly_ai') {
    check_csrf(); if (function_exists('set_time_limit')) @set_time_limit(120); [$summary,$error]=analyze_month(['month'=>$month,'totals'=>$stats,'activities'=>$typeStats,'workers'=>$workersMonth,'expense_categories'=>$categories]);
    if ($summary) $_SESSION['monthly_summary']=['month'=>$month,'text'=>$summary]; else flash($error ?? 'Summary unavailable.','error');
    redirect('admin.php?month='.urlencode($month).'#insights');
}
$summary=$_SESSION['monthly_summary'] ?? null; unset($_SESSION['monthly_summary']); $invite=$_SESSION['invite_link'] ?? null; unset($_SESSION['invite_link']);
$notificationEmail = ''; $settingsReady = true; $workerAudioEnabled = true;
try { $q=$pdo->prepare('SELECT setting_value FROM app_settings WHERE setting_key=?'); $q->execute(['notification_email']); $notificationEmail=(string)($q->fetchColumn() ?: ''); $q->execute(['worker_audio_enabled']); $soundValue=$q->fetchColumn(); $workerAudioEnabled=$soundValue === false || $soundValue === '1'; }
catch (PDOException $e) { $settingsReady = false; }
$workers=$pdo->query("SELECT id,name,email,active FROM users WHERE role='worker' ORDER BY name")->fetchAll(); $projects=$pdo->query('SELECT * FROM projects ORDER BY name')->fetchAll();
$where=['r.created_at>=?','r.created_at<?']; $params=[$start,$end];
$filterWorker=(int)($_GET['worker'] ?? 0); $filterProject=(int)($_GET['project'] ?? 0); $filterStatus=(string)($_GET['status'] ?? ''); $filterType=(string)($_GET['type'] ?? '');
$from=(string)($_GET['from'] ?? ''); $to=(string)($_GET['to'] ?? '');
if (preg_match('/^\d{4}-\d{2}-\d{2}$/',$from) && strtotime($from)!==false) { $where[]='r.created_at>=?'; $params[]=$from.' 00:00:00'; } else $from='';
if (preg_match('/^\d{4}-\d{2}-\d{2}$/',$to) && strtotime($to)!==false) { $where[]='r.created_at<?'; $params[]=date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00'; } else $to='';
if ($filterWorker>0) {$where[]='r.user_id=?';$params[]=$filterWorker;} if ($filterProject>0) {$where[]='r.project_id=?';$params[]=$filterProject;}
if (in_array($filterStatus,['pending','approved','rejected'],true)) {$where[]='r.status=?';$params[]=$filterStatus;} if (in_array($filterType,['expense','installation','delivery','receiving'],true)) {$where[]='r.type=?';$params[]=$filterType;}
$q=$pdo->prepare('SELECT r.*,u.name worker,p.name project_name,(SELECT a.action FROM audit_log a WHERE a.report_id=r.id AND a.action IN (\'AI auto-approved\',\'review updated\') ORDER BY a.id DESC LIMIT 1) last_decision,(SELECT COUNT(*) FROM report_photos ph WHERE ph.report_id=r.id) photo_count FROM reports r JOIN users u ON u.id=r.user_id LEFT JOIN projects p ON p.id=r.project_id WHERE '.implode(' AND ',$where).' ORDER BY r.created_at DESC,r.id DESC LIMIT 100'); $q->execute($params); $reports=$q->fetchAll();
page_start('Overview',$user,'dashboard');
?>
<div class="heading-row"><div><div class="eyebrow">YOUR OPERATIONS AT A GLANCE</div><h1>Welcome back, <?=e(explode(' ',trim($user['name']))[0])?> <span class="wave">✳</span></h1><p>Here’s what’s happening in your field operations.</p></div><form class="month-form" method="get"><label>Reporting month <input type="month" name="month" value="<?=e($month)?>"></label><button class="button secondary">View</button></form></div>
<section class="sound-settings" id="sound-settings" aria-label="Sound settings"><div class="sound-settings-info"><span class="sound-settings-icon" aria-hidden="true">🔊</span><div><span class="step-label">SYSTEM SETTINGS</span><h2>Worker voice instructions</h2><p>Play English voice guidance when any worker chooses an activity. Applies to all workers.</p></div></div><?php if ($settingsReady): ?><div class="sound-settings-control"><span class="sound-state <?=$workerAudioEnabled?'on':'off'?>"><?=$workerAudioEnabled?'Sound on':'Sound off'?></span><form method="post" action="admin_action.php"><?=csrf_field()?><input type="hidden" name="action" value="worker_audio"><input type="hidden" name="enabled" value="<?=$workerAudioEnabled?'0':'1'?>"><button class="button secondary" type="submit"><?=$workerAudioEnabled?'Turn sound off':'Turn sound on'?></button></form></div><?php else: ?><p class="sound-migration-warning">Import the settings migrations to manage sound.</p><?php endif; ?></section>
<div class="metric-grid"><div class="metric"><div class="metric-top"><span>Approved spending</span><span class="metric-icon blue">◈</span></div><strong><small>AED</small> <?=e(number_format((float)$stats['spending'],2))?></strong><p>Includes AI-approved amounts</p></div><div class="metric"><div class="metric-top"><span>Reports received</span><span class="metric-icon violet">▤</span></div><strong><?=e((string)$stats['total'])?></strong><p>All activity types this month</p></div><div class="metric"><div class="metric-top"><span>Awaiting review</span><span class="metric-icon amber">◷</span></div><strong><?=e((string)($stats['pending'] ?? 0))?></strong><p>Reports needing a decision</p></div><div class="metric"><div class="metric-top"><span>Active workers</span><span class="metric-icon green">♙</span></div><strong><?=count($workersMonth)?></strong><p>People in your field team</p></div></div>
<div class="dashboard-grid"><section class="panel" id="insights"><div class="section-heading"><div><span class="step-label">✦ SMART OVERVIEW</span><h2>Monthly insights</h2><p>Understand your team’s activity at a glance.</p></div><span class="pill light"><?=e(date('M Y',strtotime($start)))?></span></div><div class="insight-banner"><span class="spark">✦</span><div><strong>A clearer picture of your operations.</strong><p>Generate a Gemini summary of this month’s report counts, worker activity and approved expenses.</p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="monthly_ai"><input type="hidden" name="month" value="<?=e($month)?>"><button class="button white">Generate summary ↗</button></form></div><?php if ($summary && $summary['month']===$month && is_array($summary['text'])): $insight=$summary['text']; ?><div class="monthly-insights"><div class="monthly-insights-header"><span class="insights-mark">✦</span><div><strong>Your monthly briefing</strong><small><?=e(date('F Y',strtotime($start)))?> · Gemini insights</small></div><span class="insights-tag">AI GENERATED</span></div><p class="monthly-overview"><?=e($insight['overview'])?></p><div class="monthly-insight-columns"><div><h3><span class="insight-bullet blue-bullet">✓</span> Key highlights</h3><?php if (empty($insight['highlights'])): ?><p class="insight-empty">No highlights provided.</p><?php else: ?><ul><?php foreach($insight['highlights'] as $item): ?><li><?=e($item)?></li><?php endforeach; ?></ul><?php endif; ?></div><div><h3><span class="insight-bullet amber-bullet">!</span> Needs attention</h3><?php if (empty($insight['attention'])): ?><p class="insight-empty">No items highlighted.</p><?php else: ?><ul><?php foreach($insight['attention'] as $item): ?><li><?=e($item)?></li><?php endforeach; ?></ul><?php endif; ?></div></div><div class="insights-disclaimer">ⓘ &nbsp; AI-generated insights can be inaccurate. Verify against the original reports and records.</div></div><?php endif; ?><?php if ((int)$stats['missing_amount']>0): ?><div class="ai-warning">⚠ <?=e((string)$stats['missing_amount'])?> approved expense(s) have no amount and are excluded from spending.</div><?php endif; ?><div class="breakdown"><div><h3>Team activity <span>This month</span></h3><?php if (!$workersMonth): ?><p class="small-muted">No workers yet.</p><?php endif; ?><?php foreach($workersMonth as $wm): ?><div class="breakdown-row"><span class="avatar soft"><?=e(strtoupper(substr($wm['name'],0,1)))?></span><span class="grow"><strong><?=e($wm['name'])?></strong><small><?=e((string)$wm['pending'])?> pending</small></span><b><?=e((string)$wm['report_count'])?> <small>reports</small></b></div><?php endforeach; ?></div><div><h3>Expense categories <span>Approved only</span></h3><?php if (!$categories): ?><p class="small-muted">No approved expenses this month.</p><?php endif; ?><?php foreach($categories as $c): ?><div class="breakdown-row"><span class="small-icon expense">◈</span><span class="grow"><strong><?=e($c['category'])?></strong><small><?=e((string)$c['total'])?> expenses</small></span><b>AED <?=e(number_format((float)$c['spending'],2))?></b></div><?php endforeach; ?></div></div></section>
<aside><div class="panel quick-panel"><span class="step-label">AT A GLANCE</span><h2>Activity mix</h2><p>Reports received this month.</p><?php $typeMap=array_column($typeStats,'total','type'); foreach(['expense'=>'Expenses','installation'=>'Installations','delivery'=>'Deliveries','receiving'=>'Receiving'] as $key=>$label): ?><div class="mix-row"><span class="small-icon <?=$key?>"><?= ['expense'=>'▤','installation'=>'⌂','delivery'=>'▱','receiving'=>'▣'][$key] ?></span><strong><?=e($label)?></strong><b><?=e((string)($typeMap[$key]??0))?></b></div><?php endforeach; ?></div><div class="help-card"><span>✧</span><div><strong>Human review matters.</strong><p>Clear reports may be AI-approved. Check for mistakes.</p></div></div></aside></div>
<section class="panel"><div class="section-heading"><div><span class="step-label">DAY BY DAY</span><h2>Daily activity</h2><p>Approved expense amounts and report counts for <?=e(date('F Y',strtotime($start)))?>.</p></div></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>REPORTS</th><th>PENDING</th><th>APPROVED SPENDING</th></tr></thead><tbody><?php if (!$daily): ?><tr><td colspan="4" class="table-empty">No activity this month.</td></tr><?php endif; ?><?php foreach($daily as $d): ?><tr><td><?=e(date('d M Y',strtotime($d['day'])))?></td><td><?=e((string)$d['total'])?></td><td><?=e((string)$d['pending'])?></td><td>AED <?=e(number_format((float)$d['spending'],2))?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel reports-panel" id="reports"><div class="section-heading"><div><span class="step-label">YOUR INBOX</span><h2>Field reports</h2><p>Review submissions and keep everything moving.</p></div><span class="pill light"><?=count($reports)?> shown</span></div><form method="get" class="filters"><input type="hidden" name="month" value="<?=e($month)?>"><select name="worker" aria-label="Filter by worker"><option value="">All workers</option><?php foreach($workers as $w): ?><option value="<?=$w['id']?>" <?=$filterWorker===(int)$w['id']?'selected':''?>><?=e($w['name'])?></option><?php endforeach; ?></select><select name="project" aria-label="Filter by project"><option value="">All projects</option><?php foreach($projects as $p): ?><option value="<?=$p['id']?>" <?=$filterProject===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach; ?></select><select name="status" aria-label="Filter by status"><option value="">All statuses</option><?php foreach(['pending','approved','rejected'] as $s): ?><option value="<?=$s?>" <?=$filterStatus===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach; ?></select><select name="type" aria-label="Filter by activity"><option value="">All activities</option><?php foreach(['expense','installation','delivery','receiving'] as $t): ?><option value="<?=$t?>" <?=$filterType===$t?'selected':''?>><?=ucfirst($t)?></option><?php endforeach; ?></select><input type="date" name="from" value="<?=e($from)?>" aria-label="From date"><input type="date" name="to" value="<?=e($to)?>" aria-label="To date"><button class="button secondary">Filter</button><a href="admin.php?month=<?=e($month)?>#reports">Reset</a></form><div class="table-wrap"><table><thead><tr><th>REPORT</th><th>WORKER</th><th>PROJECT</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody><?php if (!$reports): ?><tr><td colspan="7" class="table-empty">No reports found for these filters.</td></tr><?php endif; ?><?php foreach($reports as $r): 