ecified')?></p><div class="progress-label"><span>Installation progress</span><b><?=$percent?>%</b></div><progress max="100" value="<?=$percent?>"></progress><small><?=$p['completed_units']?> of <?=$p['total_units']?> units completed</small><small>Approved <?=e($month)?> spending: AED <?=e(number_format((float)($projectSpending[(int)$p['id']] ?? 0),2))?></small></div><?php endforeach; ?></div></section>
